{
  "claim": "For non-headline series with newly joined offers and a median decline within the last three days, widening only the lower forecast tail by 25% will reduce pinball loss.",
  "mechanism": "The hypothesis is that offer entry accompanied by a recent median decline identifies episodes in which cheaper offers continue entering or displacing the middle-ranked offers, causing further downward median jumps. Widening q10's log distance below q50 represents this downside uncertainty while preserving the forecast median and upper tail.",
  "spec": {
    "when": {
      "all": [
        {"fact": "in37", "op": "==", "value": false},
        {"fact": "joined7", "op": ">", "value": 0},
        {"fact": "last_change", "op": "<", "value": 0},
        {"fact": "days_since_change", "op": "<", "value": 3}
      ]
    },
    "do": {
      "action": "scale_width",
      "lo": 1.25,
      "hi": 1.0
    }
  },
  "falsification": "Reject if pooled skill fails to rise overall or in either selection half, fewer than 200 cells across at least five series change, headline skill falls, or fewer than 90% of the 2000 ISO-week block bootstrap resamples show a rise.",
  "prior_ids_used": [],
  "expects": "I expect a modest skill improvement from reducing penalties on subsequent downward median jumps, with headline forecasts unchanged. The reported low coverage after recent changes motivates the test, but the supplied breakdowns do not establish the loss improvement or number of changed cells for this intersection."
}
